#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="E:\sdkwork-space\sdkwork-discovery\node_modules\.pnpm\@sdkwork+app-topology@file+..+sdkwork-app-topology\node_modules\@sdkwork\app-topology\node_modules;E:\sdkwork-space\sdkwork-discovery\node_modules\.pnpm\@sdkwork+app-topology@file+..+sdkwork-app-topology\node_modules;E:\sdkwork-space\sdkwork-discovery\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/sdkwork-space/sdkwork-discovery/node_modules/.pnpm/@sdkwork+app-topology@file+..+sdkwork-app-topology/node_modules/@sdkwork/app-topology/node_modules:/mnt/e/sdkwork-space/sdkwork-discovery/node_modules/.pnpm/@sdkwork+app-topology@file+..+sdkwork-app-topology/node_modules:/mnt/e/sdkwork-space/sdkwork-discovery/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../scripts/sdkwork-topology.mjs" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../../scripts/sdkwork-topology.mjs" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../../scripts/sdkwork-topology.mjs" $args
  } else {
    & "node$exe"  "$basedir/../../scripts/sdkwork-topology.mjs" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
